const bn = p => p.split("/").pop();
function prompt(t){
  return "You are an adversarial critic of " + t.lang + " grammar tips. Read the batch from \`" + t.in + "\` — an array of {id, target, english, tip}. For EACH tip apply the checks below and either return it UNCHANGED or fix it. Output a JSON array of {id, tip} with the SAME ids and count, WRITE it to \`" + t.out + "\` with the Write tool, and return {out, reviewed, fixed}.\\n\\nCHECKS:\\n" + t.critic;
}
const SCHEMA = { type:"object", additionalProperties:false, properties:{ out:{type:"string"}, reviewed:{type:"number"}, fixed:{type:"number"} }, required:["out","reviewed"] };
log("Judgment critic: " + TASKS.length + " batches across hi/ru/tr/cy.");
const results = await parallel(TASKS.map(t => () => agent(prompt(t), { label: t.lang + "/" + bn(t.out), phase: "Critic", agentType: "general-purpose", schema: SCHEMA })));
const byLang={};
for(let i=0;i<TASKS.length;i++){const t=TASKS[i],r=results[i];const L=(byLang[t.lang]=byLang[t.lang]||{ok:0,failed:0,fixed:0});if(r){L.ok++;L.fixed+=r.fixed||0;}else L.failed++;}
return { totalBatches: TASKS.length, completed: results.filter(Boolean).length, byLang };
